class Solution {
public:
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(n, -1);
        vector<int> stk;
        stk.reserve(n);
        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            while (!stk.empty() && nums[stk.back()] < nums[idx]) {
                ans[stk.back()] = nums[idx];
                stk.pop_back();
            }
            if (i < n) {
                stk.push_back(idx);
            }
        }
        return ans;
    }
};
